export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

function escapeRegExp(ch) {
  return ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeClassChar(ch) {
  if (ch === '\\' || ch === ']' || ch === '^' || ch === '-') return `\\${ch}`;
  return escapeRegExp(ch) === ch ? ch : `\\${ch}`;
}

/**
 * Split a pattern into raw segments of tokens, tracking positions for errors.
 *
 * @param {string} pattern glob pattern
 * @returns {Array<Array<object>>} list of segments, each a list of tokens
 */
function parsePattern(pattern) {
  const segments = [[]];
  const n = pattern.length;
  let i = 0;

  const currentSegment = () => segments[segments.length - 1];

  while (i < n) {
    const ch = pattern[i];

    if (ch === '/') {
      segments.push([]);
      i += 1;
      continue;
    }

    if (ch === '\\') {
      if (i + 1 >= n) throw new GlobError('trailing backslash', i);
      currentSegment().push({ kind: 'char', value: pattern[i + 1] });
      i += 2;
      continue;
    }

    if (ch === '*') {
      let j = i;
      while (j < n && pattern[j] === '*') j += 1;
      currentSegment().push({ kind: 'star', count: j - i });
      i = j;
      continue;
    }

    if (ch === '?') {
      currentSegment().push({ kind: 'qmark' });
      i += 1;
      continue;
    }

    if (ch === '[') {
      const classStart = i;
      let j = i + 1;
      let negate = false;
      if (j < n && (pattern[j] === '!' || pattern[j] === '^')) {
        negate = true;
        j += 1;
      }
      const items = [];
      let first = true;
      for (;;) {
        if (j >= n) throw new GlobError('unterminated character class', classStart);
        let c = pattern[j];
        if (c === ']' && !first) {
          j += 1;
          break;
        }
        first = false;
        if (c === '/') throw new GlobError('path separator in character class', j);
        if (c === '\\') {
          if (j + 1 >= n) throw new GlobError('trailing backslash', j);
          c = pattern[j + 1];
          j += 2;
        } else {
          j += 1;
        }
        if (pattern[j] === '-' && j + 1 < n && pattern[j + 1] !== ']') {
          const dashIndex = j;
          let endChar = pattern[dashIndex + 1];
          if (endChar === '/') throw new GlobError('path separator in character class', dashIndex + 1);
          if (endChar === '\\') {
            if (dashIndex + 2 >= n) throw new GlobError('trailing backslash', dashIndex + 1);
            endChar = pattern[dashIndex + 2];
            j = dashIndex + 3;
          } else {
            j = dashIndex + 2;
          }
          items.push({ type: 'range', from: c, to: endChar });
        } else {
          items.push({ type: 'char', value: c });
        }
      }
      currentSegment().push({ kind: 'class', negate, items });
      i = j;
      continue;
    }

    currentSegment().push({ kind: 'char', value: ch });
    i += 1;
  }

  return segments;
}

function buildClassRegex(token) {
  let inner = '';
  for (const item of token.items) {
    if (item.type === 'char') {
      inner += escapeClassChar(item.value);
    } else {
      inner += `${escapeClassChar(item.from)}-${escapeClassChar(item.to)}`;
    }
  }
  return token.negate ? `[^${inner}]` : `[${inner}]`;
}

function buildSegmentRegex(tokens, options) {
  let body = '';
  for (const tok of tokens) {
    if (tok.kind === 'char') body += escapeRegExp(tok.value);
    else if (tok.kind === 'star') body += '[^/]*';
    else if (tok.kind === 'qmark') body += '[^/]';
    else if (tok.kind === 'class') body += buildClassRegex(tok);
  }
  const beginsWithLiteralDot = tokens.length > 0 && tokens[0].kind === 'char' && tokens[0].value === '.';
  const guard = !options.dot && !beginsWithLiteralDot ? '(?!\\.)' : '';
  const flags = options.nocase ? 'i' : '';
  return new RegExp(`^${guard}${body}$`, flags);
}

function compileSegments(pattern, options) {
  const rawSegments = parsePattern(pattern);
  return rawSegments.map((tokens) => {
    if (tokens.length === 1 && tokens[0].kind === 'star' && tokens[0].count === 2) {
      return { type: 'globstar' };
    }
    return { type: 'regex', regex: buildSegmentRegex(tokens, options) };
  });
}

function matchSegments(pathSegments, patternSegments, options) {
  const memo = new Map();

  function rec(pi, si) {
    const key = `${pi},${si}`;
    if (memo.has(key)) return memo.get(key);
    let result;
    if (pi === patternSegments.length) {
      result = si === pathSegments.length;
    } else {
      const seg = patternSegments[pi];
      if (seg.type === 'globstar') {
        result = rec(pi + 1, si);
        if (!result) {
          for (let k = si; k < pathSegments.length; k += 1) {
            if (!options.dot && pathSegments[k].startsWith('.')) break;
            if (rec(pi + 1, k + 1)) {
              result = true;
              break;
            }
          }
        }
      } else {
        result = si < pathSegments.length && seg.regex.test(pathSegments[si]) && rec(pi + 1, si + 1);
      }
    }
    memo.set(key, result);
    return result;
  }

  return rec(0, 0);
}

/**
 * Compile a glob pattern into a matcher.
 *
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {(path: string) => boolean} matcher for whole paths
 */
export function compile(pattern, options = {}) {
  if (typeof pattern !== 'string') throw new GlobError('pattern must be a string');
  if (pattern.length === 0) throw new GlobError('pattern must not be empty');
  const segments = compileSegments(pattern, options);
  return (path) => {
    if (typeof path !== 'string') throw new GlobError('path must be a string');
    const pathSegments = path.split('/');
    return matchSegments(pathSegments, segments, options);
  };
}

/**
 * Test one path against one pattern.
 *
 * @param {string} path path to test
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {boolean} whether the whole path matches
 */
export function isMatch(path, pattern, options = {}) {
  const matcher = compile(pattern, options);
  return matcher(path);
}

/**
 * Keep the paths that match a pattern, in their original order.
 *
 * @param {string[]} paths paths to filter
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {string[]} the matching paths
 */
export function filter(paths, pattern, options = {}) {
  if (!Array.isArray(paths)) throw new GlobError('paths must be an array');
